WITH payload AS (SELECT $archive_payload$[{"id":"b8fe2e94-86c0-5ef9-97d4-fc627cf977cd","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتسبب يف إصابة - مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة -حق املدعي يف قبول أو عدم قبول مين املدعى عليه بنفي الدعوى -رد الدعوى.","document_number":"3423764","case_number":"33283595","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/26","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتسبب يف إصابة - مطالبة املدعي باملجازاة -إنكار املدعى عليه الدعوى -بينة املدعي غير موصلة -حق املدعي يف قبول أو عدم قبول مين املدعى عليه بنفي الدعوى -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/1/26 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3423764 :‬‬\n                   ‫َر ْق ُم الدعوى‪33283595 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34215330‬تاريخه‪1434/05/19 :‬هـ‬\n\n\n‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالضــرب وتســبب يف إصابــة ‪-‬‬\n‫مطالبــة املدعــي باملجــازاة ‪ -‬إنــكار املدعــى عليــه الدعــوى ‪ -‬بينــة املدعــي‬\n‫غيــر موصلــة ‪ -‬حــق املدعــي يف قبــول أو عــدم قبــول ميــن املدعــى عليــه‬\n                                              ‫بنفــي الدعــوى ‪ -‬رد الدعــوى‪.‬‬\n\n\n\n\n‫مــا ذكــره القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة يف‬\n                                                           ‫تســبيب حكمــه ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بــأن املدعــى عليــه قــام بضربــه علــى ركبتــه وأحــدث‬\n‫بهــا التــواء شــديدا مــع صعوبــة وآالم شــديدة مــع احلركــة‪ ،‬وطلــب‬\n‫احلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أنكــر املدعــى عليــه مــا‬\n‫جــاء يف الدعــوى‪ -‬أحضــر املدعــي شــاهد ًا وهــي زوجتــه الســابقة وابنــة‬\n‫املدعــى عليــه إال أن شــهادتها غيــر موصلــة‪ -‬املدعــي لــم يقــم بينــة موصلــة‬\n‫إلثبــات دعــواه ولــم يقبــل ميــن خصمــه علــى نفيهــا‪ -‬قضــت احملكمــة‬\n‫بصــرف النظــر عــن دعــوى املدعــي وأخلــت ســبيل املدعــى عليــه منهــا‪-‬‬\n‫قنــع املدعــى عليــه باحلكــم وعــارض عليــه املدعــي ‪ -‬قــررت محكمــة‬\n                                          ‫االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n                                                                                     ‫‪238‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬مســاعد رئيــس احملكمــة‬\n      ‫اجلزائيــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ 33283595‬وتاريــخ‬\n      ‫‪ 1433/04/24‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33767354‬وتاريــخ‬\n      ‫‪1433/4/24‬ه ـ ففــي يــوم األحــد املوافــق ‪1433/07/06‬ه ـ افتتحــت‬\n      ‫اجللســة يف موعدهــا وفيهــا حضــر (‪ ).....‬ســوري اجلنســية مبوجــب رخصــة‬\n      ‫اإلقامــة رقــم (‪ ).....‬وحضــر حلضــوره (‪ ).....‬ســوري اجلنســية مبوجــب‬\n      ‫ا إننــي كنــت زوجـ ًا البنــة‬\n                                   ‫رخصــة اإلقامــة رقــم (‪ ).....‬فأدعــى األول قائـ ً‬\n      ‫هــذا احلاضــر معــي املدعــوة (‪ ).....‬ويف أحــد األيــام ال أذكــر تاريخــه اآلن‬\n      ‫قمــت بإيصــال زوجتــي املذكــورة إلــى بيــت والدهــا هــذا احلاضــر معــي‬\n      ‫وســافرت لبــادي وبعــد عودتــي رفــض والدهــا أن تذهــب معــي بحجــة‬\n      ‫أننــي طلقتهــا ثــم ذهبــت زوجتــي برفقــة أســرتها إلــى أحــد األســواق وعنــد‬\n      ‫نزولهــم يف الســوق املســمى (‪ )...‬كلمــت زوجتــي لتذهــب معــي فقــام‬\n      ‫والدهــا هــذا احلاضــر بضربــي علــى ركبتــي وأحــدث بهــا إصابــة صــدر‬\n      ‫بهــا تقريــر طبــي مؤرخ ـ ًا يف ‪1433/1/11‬ه ـ يتضمــن التــواء شــديد يف‬\n      ‫الركبــة مــع صعوبــة واآلالم شــديدة مــع احلركــة ومــع اإليصــاء براحــة‬\n      ‫ملــدة عشــرة أيــام لــذا أطلــب تأديــب املدعــى عليــه مبــا يقــرره الشــرع جتــاه‬\n      ‫ا مــا ذكــره املدعــي‬  ‫ذلــك هــذه دعــواي وبســؤال املدعــى عليــه أجــاب قائـ ً‬\n      ‫مــن أنــه كان زوجـ ًا البنتــي وأنــه أحضــر زوجتــه عنــدي ألجــل ســفرة وأنه‬\n      ‫بعــد عودتــه جــاء إلـ ّـي وطلــب زوجتــه فرفضــت بحجــة أنــه طلقهــا وأننــا‬\n      ‫ذهبنــا إلــى الســوق املســمى ( ‪ ) ...‬يف املدينــة املنــورة برفقــة ابنتــي وأن‬\n\n‫‪239‬‬\n\f‫املدعــي حضــر لدينــا يف الســوق املذكــور فهــذا كلــه صحيــح وأمــا مــا‬\n‫ذكــره مــن أننــي قمــت بضربــه علــى ركبتــه وأحدثــت بــه إصابــة فهــذا‬\n‫غيــر صحيــح إطالقـ ًا وقــد حــدث بينــي وبينــه مشــادة كالميــة ألنــه يريــد‬\n‫أخــذ ابنتــي بالقــوة هــذه إجابتــي وبعــرض ذلك على املدعــي قال الصحيح‬\n‫مــا ذكرتــه مــن قيــام املدعــى عليــه بضربــي علــى ركبتــي وبطلــب البينــة‬\n‫منــه قــال لــدي بينــة وهــي ابنــة املدعــى عليــه املدعــوة (‪ ).....‬وهــي زوجتــي‬\n‫ســابق ًا وهــي ســجينة يف الســجن العــام وال أســتطيع إحضارهــا وأطلــب‬\n‫إحضارهــا حتــى تدلــي بشــهادتها وبــرد ذلــك علــى املدعــى عليــه قــال‬\n‫نعــم إن ابنتــي ســجينة يف الســجن العــام لوجــود عــدة قضايــا عليهــا وقــد‬\n‫كانــت زوجــة للمدعــي وقــد مت فســخ نكاحهــا مــن املدعــي هكــذا‬\n‫أجــاب كل واحــد منهمــا ويف جلســة أخــرى حضــرت املــرأة حتمــل‬\n‫اإلقامــة واملعـ ّـرف بهــا مــن قِ بــل والدهــا املدعــى عليــه وبســؤالها عمــا‬\n‫لديهــا مــن شــهادة قالــت إنــه يف شــهر محــرم مــن عــام ‪1433‬ه ـ وقبــل‬\n‫طالقــي مــن املدعــي ذهبــت إلــى الســوق مــع بعــض أهلــي واتصلــت علــى‬\n‫زوجــي ألذهــب معــه وكان والــدي قــد منعنــي مــن الذهــاب معــه وكان‬\n‫أخــي الكبيــر معنــا يف الســوق واتصــل أخــي بوالــدي وحضــر والــدي مــع‬\n‫حضــور زوجــي إلــى الســوق وصــار بينهمــا كالم مرتفــع دون متاســك‬\n‫باأليــدي وحينهــا حضــرت الشــرطة وأثنــاء تقــدم والــدي بالســيارة وقعــت‬\n‫علــى رجــل وأصابتــه اإلصابــة التــي ذكرهــا وبعدهــا ذكــر لــي املدعــي‬\n‫أنــه قــد تنــازل عــن الدعــوى ضــد والــدي ثــم تفاجــأت وأنــا يف الســجن‬\n‫بإقامــة هــذه الدعــوى علــى والــدي هــذا مــا لــدي يف هــذه القضيــة وأنــا‬\n‫منفصلــة عــن املدعــي بخلــع بتاريــخ ‪1433/04/25‬ه ـ وبعــد ذلــك جــرى‬\n‫ســؤال املدعــي هــل لديــه زيــادة بينــة قــال لــدي شــخص يدعــى ال أســتطيع‬\n\n\n                                                                                        ‫‪240‬‬\n\f      ‫إحضــاره هكــذا أجــاب فســألت املدعــي واملدعــى عليــه هــل ألحدهمــا‬\n      ‫إضافــة فأجــاب كل واحــد منهمــا بأنــه ليــس لديــه إضافــة وقــال املدعــي‬\n      ‫ويدعــى ورفــض احلضــور فأعلمــت املدعــي بــأن لــه‬        ‫إننــي كلمــت الشــاهد ُ‬\n      ‫ميــن املدعــى عليــه علــى نفــي دعــواه فقــال ال أقبــل ميينــه فأعــدت إفهامــه‬\n      ‫ـاء علــى مــا تقــدم مــن ســماع الدعــوى واإلجابــة‬    ‫فقــال ال أقبــل ميينــه‪ ،‬فبنـ ً‬\n      ‫ونظــر ًا إلــى أن املدعــي لــم ُيقــم ّبينــة موصل ـ ًة علــى دعــواه ومبــا أنــه لــم‬\n      ‫يقبــل ميــن املدعــى عليــه علــى نفــي دعــواه فقــد صرفــت النظــر عــن‬\n      ‫دعــواه ضــد املدعــى عليــه وأخليــت ســبيل املدعــى عليــه مــن هــذه الدعــوى‬\n      ‫هــذا مــا ظهــر لــي وبــه حكمــت وأفهمــت املدعــي بــأن لــه ميــن املدعــى‬\n      ‫عليــه متــى مــا رغــب وبإعــان احلكــم علــى املدعــي قــرر عــدم القناعــة‬\n      ‫باحلكــم وطلــب رفعــه إلــى محكمــة االســتئناف واســتعد بتقــدمي الئحــة‬\n      ‫اعتراضيــة وأفهــم باملراجعــة يــوم الســبت ‪1434/01/24‬ه ـ الســتالم‬\n      ‫نســخة مــن احلكــم وأن مــدة االعتــراض ثالثــون يومـ ًا مــن التاريــخ احملدد‬\n      ‫الســتالم النســخة فــإن لــم يقــدم اعتراضــه خاللهــا ســقط حقــه يف طلــب‬\n      ‫االســتئناف وقــرر املدعــى عليــه القناعــة باحلكــم وعلــى مــا تقــدم حصــل‬\n      ‫التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وع ــلى آلــه وصحبــه ح ـ ــرر‬\n                                                                     ‫يف ‪1434/01/21‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد ‪:‬‬\n      ‫فقــد جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪33767354‬‬\n      ‫وتاريــخ ‪1434/4/8‬ه ـ املرفــق بهــا الصــك رقــم ‪ 3423764‬وتاريــخ‬\n      ‫‪1434/1/26‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ).....(/‬باحملكمــة اجلزائيــة‬\n\n\n‫‪241‬‬\n\f‫باملدينــة املنــورة‪ ،‬املتضمــن دعــوى‪ ).....(/‬ســوري اجلنســية ضــد‪).....(/‬‬\n‫ســوري اجلنســية املتهــم بضــرب املدعــي علــى ركبتــه وإحــداث إلتــواء‬\n‫وألــم شــديد يف الركبــة احملكــوم فيــه مبــا دون باطنــه بدراســة احلكــم‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــة قررنــا املوافقــة علــى احلكــم‬\n‫واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبه وســلم‪،،‬‬\n\n\n\n\n                                                                               ‫‪242‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":238,"source_page_end":242,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7e1b023cec8617651dd8105422f6b28b7cab973af36b88af293a72897bceb444","normalized_text_hash":"0373bca8b4ea38c176f51fa58cf15c76f4f9d92f19352d5ab546581e167bdc2b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p238-3423764"},{"id":"88a47267-9d6b-551c-b766-8669882d0531","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب على ابن املدعي وتلفظ وتهديد بالقتل -مطالبة املدعي باملجازاة -إنكار املدعي عليه الدعوي -بينة املدعي غير موصلة -مين املدعي عليه على نفي الدعوى -رد الدعوى.","document_number":"3427654","case_number":"33404762","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/3","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب على ابن املدعي وتلفظ وتهديد بالقتل -مطالبة املدعي باملجازاة -إنكار املدعي عليه الدعوي -بينة املدعي غير موصلة -مين املدعي عليه على نفي الدعوى -رد الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"        ‫تاريخه‪1434/2/3 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3427654 :‬‬\n                         ‫َر ْق ُم الدعوى‪33404762 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                ‫‪ 34188643‬تاريخه‪1434/04/15 :‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص)‪ -‬اعتــداء بالضــرب علــى ابــن املدعــي وتلفــظ‬\n      ‫وتهديــد بالقتــل ‪ -‬مطالبــة املدعــي باملجــازاة ‪ -‬إنــكار املدعــي عليــه‬\n      ‫الدعــوي ‪ -‬بينــة املدعــي غيــر موصلــة‪ -‬ميــن املدعــي عليــه علــى نفــي‬\n                                                           ‫الدعــوى ‪ -‬رد الدعــوى‪.‬‬\n\n\n\n\n      ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                                ‫يف تســبيب حكمــه ‪.‬‬\n\n\n\n      ‫ادعــى املدعــي بواليتــه اجلبريــة علــى ولــده بــأن املدعــى عليــه احلاضر معلم‬\n      ‫البنــه يف املدرســة وقــد قــام بضربــه علــى رأســه بيــده‪ ،‬كمــا ادعــى بــأن‬\n      ‫املدعــى عليــه حــاول ضربــه هــو أيض ـ ًا وتلفــظ عليــه بألفــاظ غيــر الئقــة‬\n      ‫وهــدده بالقتــل‪ ،‬ولــذا فقــد طلــب احلكــم عليــه بعقوبــة تعزيريــة لقــاء‬\n      ‫ذلــك‪ -‬أنكــر املدعــى عليــه مــا جــاء يف الدعــوى ســوى أنــه وضــع يــده‬\n      ‫علــى رأس ابــن املدعــي ودفعــه بقصــد توجيهــه إلــى فصلــه‪ -‬املدعــي لــم‬\n      ‫يقــم بينــة موصلــة إلثبــات دعــواه وطلــب ميــن خصمــه علــى نفيهــا فأداهــا‬\n      ‫طبــق مــا طلــب منــه‪ -‬قضــت احملكمــة بــرد دعــوى املدعــي وأخلــت ســبيل‬\n      ‫املدعــى عليــه منهــا‪ -‬قنــع املدعــى عليــه باحلكــم وعــارض عليــه املدعــي‬\n\n‫‪243‬‬\n\f                  ‫‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بخميــس مشــيط برقــم ‪ 33404762‬وتاريــخ‬\n‫‪1433/06/16‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331127434‬وتاريــخ‬\n‫‪1433/6/16‬ه ـ ففــي يــوم الثالثــاء املوافــق ‪1433/10/17‬ه ـ حضــر‬\n‫املدعــي‪ ).....(/‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪).....‬‬\n‫وادعــى علــى احلاضــر معــه (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم (‪ ).....‬وبســؤال املدعــي عــن دعــواه قــال أطلــب مهلــة‬\n‫لتحريرهــا وســوف أحضرهــا يف اجللســة القادمــة وعليــه رفعــت اجللســة‬\n‫وأجلــت إلــى يــوم الثالثــاء املوافــق ‪1433/10/24‬ه ـ ويف اجللســة احملــددة‬\n‫حضــر املدعــي واملدعــى عليــه وادعــى املدعــي قائــا يف دعــواه إنــه‬\n‫بتاريــخ ‪1433/06/16‬ه ـ ذهبــت إلــى املدرســة التــي يــدرس بهــا ابنــي وقد‬\n‫اشــتكى لــي مــن أن املعلــم باملدرســة املدعــى عليــه احلاضــر قــد عصــر‬\n‫إذنه وضربه على رأســه فدخلت إلى املدرســة والقيت املعلم وســألته عن‬\n‫ســبب ضربــه البنــي فقــال لــي أنــت مــا فيــك خيــر وتكلــم علــي بــكالم‬\n‫غيــر الئــق وحــاول ضربــي وقــال لــي واهلل ألذبحــك وأنتــف حليتــك وقــام‬\n‫أوليــاء األمــور بالتدخــل بيننــا فذهبــت إلــى الشــرطة وقدمــت شــكوى‬\n‫لــذا أطلــب معاقبــة املدعــى عليــه علــى ضربــه البنــي وعلــى تلفظــه علــي‬\n‫بألفــاظ ســيئة وتهديــده لــي بالقتــل هــذه دعــواي وبســؤال املدعــى عليــه‬\n‫اإلجابــة أجــاب قائــا مــا ذكــره املدعــي غيــر صحيــح والصحيــح أنــه يف‬\n\n                                                                                  ‫‪244‬‬\n\f      ‫التاريــخ املشــار إليــه وأثنــاء عملــي كمشــرف يف املدرســة شــاهدت ابــن‬\n      ‫املدعــى عليــه متواجــد مــع طــاب الصــف األول االبتدائــي وهــو يــدرس‬\n      ‫يف الصــف الرابــع االبتدائــي وهــو طالــب مشــاغب وســبق ضربــه ألحــد‬\n      ‫الطــاب فمســكته مــع إذنــه اليســرى وقلــت لــه اذهــب إلــى فصلــك‬\n      ‫وضربتــه ضربــه خفيفــة علــى رأســه ولــم حتــدث أي أثــر يف جســمه ثــم‬\n      ‫بعــد ذلــك حضــر املدعــي والــده وقــال لــي ملــاذا ضربــت ابنــي فقلــت لــه‬\n      ‫اســأل ولــدك مــاذا فعــل اليــوم ثــم تلفــظ علــي بألفــاظ غيــر الئقــة ورفــع‬\n      ‫صوتــه وأحــدث شوشــرة وضجــة يف املدرســة وســبق أن فعــل مثــل ذلــك‬\n      ‫فقلــت لــه عيــب عليــك ذلــك فقــال لــي واهلل ألرميــك بالرشــاش وقــال لــي‬\n      ‫كلمــة قبيحــة فقلــت لــه اســتح علــى حليتــك تــرى واجــب كالمــك هــذا‬\n      ‫نتــف حليتــك هــذا مــا حصــل وعليــه شــهود ومحاضــر واملدعــي لــه ســوابق‬\n      ‫مــع كثيــر مــن املدرســن باملدرســة والتلفــظ عليهــم بألفــاظ نابيــة وعــدم‬\n      ‫احترامــه لنظــام املدرســة هــذه إجابتــي وبســؤال املدعــي عــن بينتــه علــى‬\n      ‫دعــواه قــال ليــس لــدي إال مــا يف أوراق املعاملــة هكــذا قــرر ورفعــت‬\n      ‫اجللســة للنظــر واالطــاع علــى أوراق املعاملــة وأجلــت إلــى يــوم الثالثــاء‬\n      ‫املوافــق ‪1433/12/28‬ه ـ ويف اجللســة احملــددة حضــر املدعــي واملدعــى‬\n      ‫عليــه وجــرى االطــاع علــى بــاغ املدعــي املــدون يف امللــف املرفــق لفــه‬\n      ‫رقــم (‪ )1‬واملتضمــن كمــا جــاء يف دعــواه كمــا جــرى االطــاع علــى‬\n      ‫احملضــر املعــد مــن مديــر مدرســة اإلمــام النســائي واملرفــق باملعاملــة لفــه‬\n      ‫رقــم (‪ )4‬واملتضمــن أنــه بتاريــخ ‪1433/5/12‬ه ـ دخــل ولــي أمــر الطالــب‬\n      ‫‪ /‬املدرســة نهايــة الــدوام وقــام مبشــادة كالميــة مــع املعلــم ‪ /‬باتهــام‬\n      ‫املعلــم بضــرب ابنــه وأخــذ ولــي أمــر الطالــب بتهديــد املعلــم باســتخدام‬\n      ‫الســاح فقــام مجموعــة مــن املعلمــن بإخــراج ولــي األمــر مــن املدرســة‬\n\n\n‫‪245‬‬\n\f‫أه ـ كمــا جــرى االطــاع علــى احملضــر املعــد مــن معلمــي املدرســة كل‬\n‫مــن ‪ /‬و ‪ /‬و ‪ /‬املرفــق باملعاملــة لفــه رقــم (‪ )6‬املتضمــن أن املواطــن ‪/‬‬\n‫كثيــر الدخــول إلــى املدرســة وأخــذ ولــده دون اســتاذان ورغــم احترامنــا‬\n‫لــه متــادى يف ذلــك وتلفــظ بألفــاظ ســيئة علينــا وقــد طلبنــا منــه إبقــاء‬\n‫ابنــه يف املدرســة حتــى نهايــة الــدوام ولــم ينصــاع ‪.‬أ‪.‬ه ـ وجــرى ســؤال‬\n‫املدعــي هــل هنــاك تقريــر طبــي عــن إصابــة ابنــه املذكــور فقــرر قائــا‬\n‫ال يوجــد تقريــر طبــي حيــث أنــه وقــت احلادثــة كانــت هنــاك مســاعي‬\n‫لصلــح فلــم أذهــب بــه إلــى املستشــفى ولــم ينتــج عــن اعتــداء املدعــي عليــه‬\n‫علــى أبنــي أي اثــر إال احمــرار يف اإلذن فجــرى افهــام املدعــي بــأن لــه‬\n‫ميــن املدعــى عليــه علــى نفــي دعــواه تهديــده بالقتــل ومحاولــة اعتدائــه‬\n‫عليــه وتلفظــه عليــه فقــرر قائــا أطلــب ميــن املدعــى عليــه علــى ذلــك‬\n‫هكــذا قــرر وبعــرض ذلــك علــى املدعــى عليــه قــرر قائــا ال مانــع لــدي‬\n‫مــن بــذل اليمــن املطلوبــة فأذنــت لــه ثــم تلفــظ قائــا واهلل العظيــم لــم‬\n‫أهــدد املدعــي هــذا احلاضــر بالقتــل ولــم أحــاول االعتــداء عليــه ولــم‬\n‫أتلفــظ عليــه بألفــاظ ســيئة ســوى مــا ذكرتــه يف إجابتــي علــى الدعــوى‬\n‫هكــذا حلــف وقــرر املدعــى عليــه قائــا يف اجللســة الســابقة الحظــت‬\n‫وجــود عبــارة ( ضربتــه علــى رأســه ) وقــد صيغــت هــذه العبــارة خــاف‬\n‫ملــا أجبــت بــه لفضيلتكــم عنــد ســؤالي وقــد آثــرت أن أقــدم اعتراضــي‬\n‫علــى هــذه العبــارة يف جلســة اليــوم نظــرا لزحمــة اجللســات يف ذلــك اليــوم‬\n‫واملواعيــد وأيضــا لدخــول إقامــة صــاة الظهــر فأرجــو مــن فضيلتكــم‬\n‫صياغــة هــذه العبــارة كمــا بنيتهــا لفضيلتكــم ومثلتهــا أمامكــم ألن‬\n‫بصيغتهــا احلاليــة تختلــف كليــا عمــا حــدث وتفهــم عنــد قراءتهــا للســامع‬\n‫والقــارئ بعكــس مــا حــدث فلقــد وجهتــه إلــى الذهــاب علــى فصلــه بــأن‬\n\n\n                                                                                       ‫‪246‬‬\n\f      ‫المســت أصابــع يــدي رأســه كتوجيــه لــه وجعلــه يستشــعر خطــأه واهلل‬\n      ‫يشــهد علــى ذلــك فالطالــب منــذ أن درس عندنــا لــم أمــد يــدي عليــه‬\n      ‫هــو أو غيــره هــذا مــا حــدث هكــذا قــرر وأضــاف قائــا أطلــب مجــازاة‬\n      ‫املدعــي علــى تشــهيره لــي يف الشــرط وإدارة التعليــم واحملاكــم يف‬\n      ‫دعــوى غيــر صحيحــة أطلــب تعويضــي عــن ذلــك ماديــا وال أطالبــه بــأي‬\n      ‫شــيء لقــاء تلفظــه علــي بألفــاظ ســيئة وذلــك تقديــرا ملجلــس القضــاء‬\n      ‫وحيــاء مــن ذكــر مــا قالــه لــي املدعــي كمــا أطلــب معاقبــة املدعــي علــى‬\n      ‫تهديــده لــي بالســاح ولــدي شــهود علــى ذلــك وهــم مــن منســوبي املدرســة‬\n      ‫وأطلــب ســماع شــهادتهم هكــذا قــرر وأحضــر للشــهادة ‪ /‬وجــرى تدويــن‬\n      ‫هويتهــم وشــهادتهم يف الضبــط ورفعــت اجللســة النتهــاء وقتهــا ويف يــوم‬\n      ‫الســبت املوافــق‪ 1434/02/02‬ه ـ حضــر املدعــي واملدعــى عليــه فبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وبنــاء علــى إنــكار املدعــى عليــه‬\n      ‫دعــوى املدعــي وبنــاء علــى طلــب املدعــي ميــن املدعــى عليــه علــى الصيغــة‬\n      ‫املذكــورة وحلــف املدعــى عليــه اليمــن املطلوبــة لــذا قــررت رد طلــب‬\n      ‫املدعــي وأخليــت ســبيل املدعــى عليــه مــن هــذه الدعــوى وبــه حكمــت‬\n      ‫وأفهمــت املدعــى عليــه بأنــه إذا كان لــه دعــوى علــى املدعــي فيقيمهــا‬\n      ‫يف دعــوى مســتقلة وبعــرض احلكــم علــى املدعــي قــرر اعتراضــه علــى‬\n      ‫احلكــم وطلــب رفعــه إلــى محكمــة االســتئناف فأفهــم بــأن عليــه‬\n      ‫مراجعــة احملكمــة الســتالم نســخة مــن احلكــم خــال خمســة أيــام‬\n      ‫وتقــدمي اعتراضــه عليــه خــال مــدة ثالثــن يومــا فــإن لــم يقــدم اعتراضــه‬\n      ‫خاللهــا ســقط حقــه يف االعتــراض وبعرضــه علــى املدعــى عليــه قــرر‬\n      ‫القناعــة بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/02‬ه ـ‬\n\n\n‫‪247‬‬\n\f‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط برقــم‬\n‫‪ 331822888‬وتاريــخ ‪1434/4/2‬ه املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ‪ ).....(/‬برقــم ‪ 3427654‬وتاريــخ‬\n‫‪1434/2/3‬ه اخلــاص بدعــوى املدعــى‪ ).....(/‬ضــد ‪ ).....( /‬ســعوديي‬\n‫اجلنســية يف قضيــة (إعــداء بالضــرب) علــى الصفــة املوضحــة يف القــرار‬\n‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم‪ .‬واهلل‬\n                    ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪248‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":243,"source_page_end":248,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"8e4d5a3d87d2bcbf415ce77f0f110a075803010fe6da682c7c1f986795461268","normalized_text_hash":"840d4435ec8957b71946d70acd8b998f6ada042d13be9a10937f9ee37a271831","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p243-3427654"},{"id":"b3512a30-4086-57ac-86a4-7beaaadee5e1","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير -سب -تعزير -مطالبة بتعزير املدعى عليها للسب -الدفع بأن السب كان يف مجلس القضاء يف دعوى حضانة حكم بها لصالح املدعي -السب حصل أثناء نظر القضية لذا ردت المحكمة الدعوى .","document_number":"33434440","case_number":"33412698","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض كان يوجد لدي جلسة يف ذلك اليوم لدى املازم باملكتب القضائي الشيخ ()","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/22","year":"1434","subject":"إيذاء الغير -سب -تعزير -مطالبة بتعزير املدعى عليها للسب -الدفع بأن السب كان يف مجلس القضاء يف دعوى حضانة حكم بها لصالح املدعي -السب حصل أثناء نظر القضية لذا ردت المحكمة الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/10/22 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33434440 :‬‬\n                          ‫َر ْق ُم الدعوى‪33412698 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3439827‬تاريخه‪1434/2/18 :‬هـ‬\n\n\n       ‫إيــذاء الغيــر ‪ -‬ســب ‪ -‬تعزيــر ‪ -‬مطالبــة بتعزيــر املدعــى عليهــا للســب‬\n       ‫‪ -‬الدفــع بــأن الســب كان يف مجلــس القضــاء يف دعــوى حضانــة حكــم‬\n       ‫بهــا لصالــح املدعــي ‪ -‬الســب حصــل أثنــاء نظــر القضيــة لــذا ردت‬\n                                                             ‫احملكمــة الدعــوى ‪.‬‬\n\n\n\n\n       ‫‪-1‬حديــث (يــا رســول اهلل إنــه رجــل فاجــر ال يبالــي علــى مــا حلــف) رواه‬\n                                                                                  ‫مســلم‬\n                                         ‫‪-2‬املادة ‪178‬من نظام املرافعات الشرعية‬\n\n\n\n\n       ‫املدعــي يطالــب بتعزيــر املدعــى عليهــا شــرعا لســبه واتهامــه بالنفــاق‬\n       ‫والكــذب وطلــب كــف أذاهــا عنــه ‪ -‬أقــرت املدعــى عليهــا مبــا جــاء يف‬\n       ‫دعــوى املدعــي وذكــرت أنهــا لــم تتمالــك نفســها عنــد النطــق باحلكــم‬\n       ‫حلضانــة املدعــي البنتــه وال تعلــم مــاذا قالــت ‪ -‬ومبــا أن املدعــى ذكــر يف‬\n       ‫دعــواه أن املدعــى عليهــا تلفظــت بالســب بعــد النطــق باحلكــم كونهــا لم‬\n       ‫تتمالــك نفســها وملــا ورد يف مــا رواه اإلمــام مســلم مــن حديــث احلضرمــي‬\n       ‫والكنــدي حــن اختصمــا عنــد رســول اهلل يف أرض فقــال النبــي صلــى‬\n       ‫اهلل عليــه وســلم للحضرمــي ألــك بينــة؟ قــال ال قــال فلــك ميينــه قــال (يــا‬\n\n‫‪249‬‬\n\f‫رســول اهلل إن الرجــل فاجــر وال يبالــي علــى مــا حلــف وليــس يتــورع عــن‬\n‫شــيء) ولــم يثبــت أن النبــي صلــى اهلل عليــه وســلم عــزره علــى اتهامــه‬\n‫خلصمــه بالفجــور لــذا ردت احملكمــة دعــوى املدعــي وأخلــت ســبيل‬\n                     ‫املدعــي عليهــا ‪ -‬اعتــرض املدعــي ‪ُ -‬صـ ِّـدق احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي (‪ ).....‬القاضــي يف احملكمــة اجلزائيــة وبنــاء‬\n‫علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالرياض‬\n‫وتاريــخ ‪1433/06/18‬ه ـ املقيــدة باحملكمــة ‪ 33115343‬وتاريــخ‬\n‫‪1433/06/18‬ه ففــي يــوم األحــد املوافق‪1433/10/22‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪10 : 45‬وفيهــا حضــر املدعــي (‪ ).....‬ســعودي اجلنســية‬\n‫وحضــر حلضــوره املدعــى عليهــا (‪ ).....‬ســعودي اجلنســية واملعرفــة مــن قبــل‬\n‫اخيهــا وبســؤال املدعــي عــن دعــواه أجــاب قائــا ففــي يوم االثنــن املوافق‬\n‫‪1433/3/28‬ه ـ يف الــدور التاســع يف املكتــب القضائــي رقــم (‪ )27‬لــدى‬\n‫فضيلــة الشــيخ (‪ ).....‬القاضــي باحملكمــة العامــة بالريــاض كان يوجــد‬\n‫لــدي جلســة يف ذلــك اليــوم لــدى املــازم باملكتــب القضائي الشــيخ (‪).....‬‬\n‫القاضــي ضــد املدعــى عليهــا يف دعــوى مقيمتهــا املدعــى عليهــا علــى‬\n‫ابنتهــا بــأن تختــار البنــت مــع مــن تعيــش فقــال الشــيخ أنــه يريــد أن يشــاور‬\n‫البنــت فيمــن تريــد أن تعيــش معــه مــن أمهــا أو أبيهــا فاختــارت البنــت‬\n‫العيــش معــي وعنــد قيــام فضيلــة املــازم بالنطــق باحلكــم بــأن تعيــش‬\n‫البنــت عنــدي وبعــد حلظــات لــم تتمالــك املدعــى عليهــا نفســها وأخــذت‬\n‫تســبني وتتهمنــي باملنافــق والكــذاب وذلــك يف املكتــب املختصــر وذلك‬\n‫أمــام وبحضــور القاضــي وأختــي وابنتــي واحملامــي الــذي قمــت بتوكيلــه‬\n\n                                                                                         ‫‪250‬‬\n\f      ‫حلضــور اجللســة لــذا أطلــب مــن فضيلتكــم تعزيرهــا شــرع ًا مبــا يكــف‬\n      ‫أذاهــا عنــي هــذه دعــواي وبعرضهــا علــى املدعــى عليهــا أحابــت قائلــة‬\n      ‫إن املدعــي كان زوجــي ومت خلعــي منــه مبوجــب صــك شــرعي مــن‬\n      ‫احملكمــة العامــة بالريــاض وبينــي وبينــه عــدة قضايــا رفعتهــا عليــه‬\n      ‫وهــي قضيــة احلضانــة والزيــارة البنتــي (‪ ).....‬وقضيــة النفقــة لــي والبنتــي‬\n      ‫وقضيــة ماليــة وهــو رفــع علــي هــذه القضيــة وقضيــة اتهامــي بتصويــر‬\n      ‫ابنتــي وعندمــا مت احلكــم علــي بحضانــة ابنتــي لــه لــم أمتالــك نفســي‬\n      ‫لتأثيــر احلكــم علــى نفســيتي وال أعلــم مــاذا قلــت لــه هــذه إجابتــي‬\n      ‫فبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة ومبــا أن املدعــي ذكــر يف‬\n      ‫دعــواه أن املدعــى عليهــا تلفظــت بالســب بعــد النطــق باحلكــم كونهــا‬\n      ‫لــم تتمالــك نفســها ومبــا أن املدعــى عليهــا ذكــرت أنهــا ال تعلــم مــاذا‬\n      ‫قالــت عندمــا لــم تتمالــك نفســها عنــد النطــق باحلكــم وعلــى فــرض‬\n      ‫أنهــا اتهمــت املدعــي بالكــذب والنفــاق يف املجلــس الشــرعي فإنهــا ال‬\n      ‫تعــزر وعليــه يحمــل قولــه يف احلديــث ((يــا رســول اهلل إنــه فاجــر ال يبالــي‬\n      ‫مــا حلــف عليــه )) حديــث احلضرمــي والكنــدي حيــث قــال احلضرمــي‬\n      ‫يــا رســول اهلل إن هــذا قــد غلبنــي علــى أرض لــي كانــت ألبــى فقــال‬\n      ‫الكنــدي هــي أرضــى يف يــدى أزرعهــا ليــس لــه فيهــا حــق فقــال رســول‬\n      ‫اهلل ‪ -‬صلــى اهلل عليــه وســلم ‪ -‬للحضرمــي (( ألــك بينــة )) قــال ال قــال‬\n      ‫((فلــك ميينــه )) قــال يــا رســول اهلل إن الرجــل فاجــر ال يبالــى علــى مــا‬\n      ‫حلــف عليــه وليــس يتــورع مــن شــيء فقــال ((ليــس لــك منــه إال ذلــك‬\n      ‫)) فانطلــق ليحلــف فقــال رســول اهلل ‪ -‬صلــى اهلل عليــه وســلم ‪ -‬ملــا‬\n      ‫أدبــر (( أمــا لئــن حلــف علــى مالــه ليأكلــه ظلمــا ليلقــن اهلل وهــو عنــه‬\n      ‫معــرض )) رواة اإلمــام مســلم ولــم يثبــت عــن النبــي صلــى اهلل عليــه وســلم‬\n\n\n‫‪251‬‬\n\f‫أنــه عــزره علــى اتهامــه خلصمــه بالفجــور وهــو مــا رجحــه ابــن ســعدي‬\n‫رحمــه اهلل ‪ .‬لــذا فقــد رددت دعــوى املدعــي وأخليــت ســبيل املدعــى‬\n‫عليهــا وبــه حكمــت وبعــرض احلكــم علــى املدعــي قــرر عــدم القناعــة‬\n‫وطلــب اســتئناف احلكــم بالئحــة فأجبتــه لذلــك وأفهمتــه باملــادة الثامنــة‬\n‫والســبعني بعــد املائــة مــن نظــام املرافعــات الشــرعية وهــذا نصهــا ((مــدة‬\n‫االعتــراض بطلــب التمييــز ثالثــون يومـ ًا فــإذا لــم يقــدم اخلصــم اعتراضـ ًا‬\n‫خــال هــذه املــدة ســقط حقــه فيطلــب التمييــز وعلــى احملكمــة اتخــاذ‬\n‫محضــر بذلــك يف ضبــط القضيــة والتهميــش علــى الصــك وســجله بــأن‬\n‫احلكــم قــد اكتســب القطعيــة)) وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/10/22‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم‬\n‫‪ 331153438‬وتاريــخ ‪1434/1/18‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n‫فضيلــة القاضــي باحملكمــة الشــيخ (‪ ).....‬املســجل برقــم ‪33434440‬‬\n‫وتاريــخ ‪1433/10/22‬ه اخلــاص بدعــوى (‪ ).....‬ضــد املــرأة (‪ ).....‬التهامهــا‬\n‫بســبه وشــتمه علــى النحــو املوضــح بالقــرار وطلبــه تعزيرهــا شــرع ًا مبــا‬\n‫يكــف أذاهــا عنــه املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل‬\n‫بــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا باألكثريــة‬\n‫املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                  ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                     ‫‪252‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":249,"source_page_end":252,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"093cb9a8d4095269ac32b265a4c7a50960084a6d80d81d4b694f292c4d3aca92","normalized_text_hash":"72c4712e547aa7d67b9170a67b5c0b20a7a0f6c37ecbd319e34bddd7f0e75671","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p249-33434440"},{"id":"69effb5f-744a-52ff-8b85-7c783c21c386","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -دعاوى كيدية -مطالبة املدعي بكف األذى والتعزير -وجود خصومات بن طريف اخلصومة -عدم ثبوت كيدية الدعوى -رد الدعوى -التماس إعادة نظر -رفض طلب","document_number":"34191050","case_number":"33503913","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم -تقدم املدعي بالتماس إعادة نظر لألسباب املوضحة فيه- رفض طلب االلتماس","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/17","year":"1434","subject":"إيذاء الغير (حق خاص) -دعاوى كيدية -مطالبة املدعي بكف األذى والتعزير -وجود خصومات بن طريف اخلصومة -عدم ثبوت كيدية الدعوى -رد الدعوى -التماس إعادة نظر -رفض طلب","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/17 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34191050 :‬‬\n                         ‫َر ْق ُم الدعوى‪33503913 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34290673‬تاريخه‪1434/8/8:‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص)‪ -‬دعــاوى كيديــة‪ -‬مطالبــة املدعــي بكــف‬\n      ‫األذى والتعزيــر‪ -‬وجــود خصومــات بــن طــريف اخلصومــة‪ -‬عــدم ثبــوت‬\n      ‫كيديــة الدعــوى‪ -‬رد الدعــوى‪ -‬التمــاس إعــادة نظــر‪ -‬رفــض طلــب‬\n                                                                ‫االلتمــاس ‪.‬‬\n\n\n\n\n             ‫‪ -1‬املادة (‪ )192‬من نظام املرافعات الشرعية ولوائحه التنفيذية‪.‬‬\n                    ‫‪ -2‬املادتان (‪ )206‬و(‪ )208‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه اتهمــه بأنــه قــام بحــرق ســيارته دون‬\n      ‫أي دليــل ممــا أدى إلــى تشــويه ســمعته كمــا أقــام ضــده عــدة دعــاوى‬\n      ‫قضائيــة بغيــر حــق‪ ،‬وطلــب كــف أذاه عنــه واحلكــم عليــه بعقوبــة‬\n      ‫تعزيريــة لقــاء ذلــك‪ -‬أقــر املدعــى عليــه بأنــه قــدم شــكاوى ودعــاوى‬\n      ‫ضــد املدعــي ودفــع بأنهــا ليســت كيديــة لكــون املدعــي خصــم لــه‬\n      ‫وقــد صــدرت عليــه عــدة أحــكام يف قضايــا بينهمــا‪ -‬اطلعــت احملكمــة‬\n      ‫علــى األحــكام الصــادرة ضــد املدعــى عليــه لصالــح املدعــي فلــم جتــد‬\n      ‫فيهــا مــا يثبــت كيديتهــا‪ -‬قضــت احملكمــة بصــرف النظــر عــن دعــوى‬\n      ‫املدعــي وأخلــت ســبيل املدعــى عليــه منهــا‪ -‬قنــع املدعــى عليــه باحلكــم‬\n\n‫‪253‬‬\n\f‫وعــارض عليــه املدعــي‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى‬\n‫احلكــم‪ -‬تقــدم املدعــي بالتمــاس إعــادة نظــر لألســباب املوضحــة فيــه‪-‬‬\n                                                  ‫رفــض طلــب االلتمــاس‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة يف محافظــة جــدة املســاعد برقــم ‪33503913‬‬\n‫وتاريــخ ‪1433/8/4‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331461699‬وتاريــخ‬\n‫‪ 1433/08/04‬ه ـ ففــي يــوم الســبت املوافــق ‪1433/11/13‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 08 : 45‬وفيهــا حضــر ســعودي اجلنســية حامــل ســجل‬\n‫مدني رقم (‪ )......‬وحضر حلضوره املدعى عليه‪ ،‬ســعودي اجلنســية حامل‬\n‫ا هــذا الشــخص املاثــل‬ ‫ســجل مدنــي رقــم (‪ )....‬وقــرر املدعــي دعــواه قائـ ً‬\n‫أمامكــم اتهمنــي بالباطــل بحــرق ســيارته أمــام مبنــى مؤسســة عــكاظ‬\n‫للصحافــة والنشــر يــوم األربعــاء ‪1432/11/7‬ه بــدون أي بينــه أو دليــل‬\n‫ممــا أدى إلــى تشــوية ســمعتي يف مقــر عملــي وبــن زمالئــي وأســرتي‪،‬‬\n‫وأقــام علــي دعــوى نظرهــا فضيلتكــم بتاريــخ‪1433/05/01 :‬ه وكان‬\n‫احلكــم بصــرف النظــر عــن مــا كان يدعيــه املدعــي لعدم وجــود أي بينه‬\n‫لديــه وقــدم اعتراضــه علــى احلكــم ومت إرســاله إلــى هيئــة التمييــز ومت‬\n‫متييــزه بتاريــخ‪1433/07/05 :‬ه ـ وقــد ســبق وأن اتهمنــي بأني شــاهد زور‬\n‫يف قضيــة ســابقة‪ ،‬وأقمــت عليــه دعــوى نظرهــا فضيلــة الشــيخ ‪ /‬وقــد‬\n‫مت صــدور الصــك املرفــق صورتــه برقــم ‪/2/87‬ق وتاريخ‪1430/4/2‬ه ـ‬\n‫بتوبيخــه يف املجلــس الشــرعي ومت احلكــم بأخــذ التعهــد عليــه بعــدم‬\n\n                                                                                    ‫‪254‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":253,"source_page_end":254,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aae0e65fea502f4e3f39e2ae399d65028810231a8133037f078785dabac36cce","normalized_text_hash":"5dd442038a421db9a985960f30fc10b214d35310401236bffa13764359b12c36","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p253-34191050"},{"id":"dc8cf205-d086-5667-a2e1-12492ec78ccf","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتهديد برسائل اجلوال -مطالبة املدعي باملجازاة -إقرار املدعى عليه بالدعوى -إيجابية التقرير الطبي للمدعي -عجز املدعى عليه عن إثبات دفعة -إدانة","document_number":"34186344","case_number":"33574767","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم بعد اإلجراء األخير","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/13","year":"1434","subject":"إيذاء الغير (حق خاص) -اعتداء بالضرب وتهديد برسائل اجلوال -مطالبة املدعي باملجازاة -إقرار املدعى عليه بالدعوى -إيجابية التقرير الطبي للمدعي -عجز املدعى عليه عن إثبات دفعة -إدانة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/13 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34186344 :‬‬\n                         ‫َر ْق ُم الدعوى‪33574767 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪34232701‬تاريخه‪1434/6/6 :‬هـ‬\n\n\n      ‫إيــذاء الغيــر (حــق خــاص) ‪ -‬اعتــداء بالضــرب وتهديــد برســائل اجلــوال‬\n      ‫‪ -‬مطالبــة املدعــي باملجــازاة ‪ -‬إقــرار املدعــى عليــه بالدعــوى ‪ -‬إيجابيــة‬\n      ‫التقريــر الطبــي للمدعــي ‪ -‬عجــز املدعــى عليــه عــن إثبــات دفعــة ‪ -‬إدانــة‬\n                                                                        ‫املدعــى عليــه‪.‬‬\n\n\n\n\n      ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                                ‫يف تســبيب حكمــه ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بــأن املدعــى عليــه احلاضــر معــه ابــن أختــه وقد قــام بضربه‬\n      ‫بيده مما تســبب يف إصابته بكدمة يف الشــفة العليا وســحجة بالركبة‬\n      ‫اليســرى كمــا قــام بتهديــده عــن طريــق رســائل اجلــوال‪ ،‬ولــذا فقــد طلــب‬\n      ‫احلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلــك‪ -‬أقــر املدعــى عليــه بضــرب‬\n      ‫املدعــي وتهديــده مبــا جــاء يف دعــواه ودفــع بــأن املدعــي هــو مــن ابتــدأه‬\n      ‫بالضــرب وبإرســال رســائل التهديــد‪ -‬طلبــت احملكمــة مــن املدعــى عليــه‬\n      ‫إثبــات مــا دفــع بــه فعجــز عــن ذلــك وطلــب ميــن املدعــي علــى نفــي ذلــك‬\n      ‫فأداهــا طبــق مــا طلــب منــه‪ -‬املدعــى عليــه تســبب يف إصابــة املدعــي‬\n      ‫بكدمــة وتــورم بالشــفة العليــا وســحجة بالركبــة اليســرى ومــدة شــفاءه‬\n\n‫‪261‬‬\n\f‫املتوقعــة ثالثــة أيــام حســب التقريــر الطبــي‪ -‬قضــت احملكمــة بإدانــة‬\n‫املدعــى عليــه مبــا نســب إليــه وقــررت ســجنه ملــدة شــهر واحــد وجلــده‬\n‫ســبعني جلــدة علــى دفعتــن وصرفــت النظــر عــن دعــوى املدعــى عليــه‬\n‫بضــرب املدعــي لــه لعــدم ثبوتهــا‪ -‬قنــع املدعــي باحلكــم وعــارض عليــه‬\n‫املدعــى عليــه‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم بعــد‬\n                                                            ‫اإلجــراء األخيــر‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬املــازم القضائــي يف احملكمــة‬\n‫اجلزئيــة باألحســاء يف املكتــب القضائــي الســادس وبنــاء علــى املعاملــة‬\n‫احملالــة مــن رئيــس احملكمــة اجلزئيــة باألحســاء برقــم ‪33574767‬‬\n‫يف ‪1433/9/13‬ه ـ واملقيــدة برقــم ‪ 331703621‬يف ‪1433/09/13‬ه ـ‬\n‫وبنــاء علــى تعميــدي مــن فضيلــة الشــيخ ‪ ).....(/‬القاضــي باحملكمــة‬\n‫اجلزئيــة مبحافظــة األحســاء لنظــر هــذه القضيــة ففــي يــوم األحــد‬\n‫املوافــق ‪1434/1/11‬ه ـ افتتحــت اجللســة األولــى يف متــام الســاعة الثامنــة‬\n‫والنصــف صباحـ ًا وفيهــا حضــر املدعــي ‪ ).....(/‬ســعودي بالســجل املدنــي‬\n‫رقــم (‪ ).....‬وحضــر حلضــوره املدعــى عليــه (‪ ).....‬ســعودي بالســجل املدنــي‬\n‫رقــم (‪ ).....‬وبســؤال املدعــي عــن دعــواه قــال إن هــذا احلاضــر معــي ‪/‬‬\n‫ا لــي‬‫ابــن أختــي قــام بتهديــدي عــن طريــق إرســال رســالة باجلــوال قائ ـ ً‬\n‫[انتبــه لنفســك ال أشــيلك واســتر علــى نفســك يــا بوقــرون وإذا أنــت رجــال‬\n‫قابلنــي باحلرمــة يــا كلــب تنبــح مــن بعيــد] كمــا قــام بضربــي ممــا نتــج‬\n‫عــن ذلــك إصابتــي بكدمــة بالشــفة العليــا وســحجه بالركبــة اليســرى‬\n‫أطلــب تأديبــه علــى ذلــك هــذه دعــواي وبعــرض ذلــك علــى املدعــى عليــه‬\n\n                                                                                    ‫‪262‬‬\n\f      ‫قــال إن مــا ذكــره املدعــي مــن قيامــي بتهديــده بالصيغــة املذكــورة يف‬\n      ‫الدعــوى فصحيــح حيــث إن املدعــي هــو الذي بدء بإرســال رســائل تهديد‬\n                                        ‫ا [ بتوطَّ ــاك ] كمــا تلفــظ علــي قائـ ً‬\n      ‫ا [ يــا النغــل ويــا قــواد ويــا‬                                         ‫لــي قائـ ً‬\n      ‫حمــار ] وأمــا بالنســبة عــن قيامــي بضربــه فهــو الــذي قــام بضربــي ابتــداء‬\n      ‫فلمــا ضربنــي قمــت بضربــه هكــذا أجــاب وبعــرض ذلــك علــى املدعــي‬\n      ‫قــال إن مــا ذكــره املدعــي مــن أنــي قمــت بإرســال الرســائل وتهديــده‬\n      ‫والتلفــظ عليــه وضربــه ابتــداء فغيــر صحيــح بــل هــو الــذي قــام بضربــي‬\n      ‫حيــث يوجــد خــاف عائلــي قــدمي بينــي وبــن أم املدعــى عليــه هكــذا‬\n      ‫أجــاب هــذا فتــم اطالعــي علــى تقريــر الطبــي الصــادر مــن مستشــفى‬\n      ‫األميــر ســعود بــن جلــوي باألحســاء برقــم (‪ )41/26/10/4/4526‬يف‬\n      ‫‪1433/8/26‬ه املرفــق يف املعاملــة علــى اللفة رقم (‪ )10‬ويتضمن (تعرض‬\n      ‫املدعــي لكدمــة وتــورم بالشــفة العليــا وســحجة بالركبــة اليســرى‬\n      ‫ســبب اإلصابــة اعتــداء بالضــرب مــدة الشــفاء ثالثــة أيــام مــا لــم حتــدث‬\n      ‫مضاعفات)أ‪.‬ه ـ وبعرضــه علــى املدعــى عليــه قــال صحيــح هكذا أجاب‬\n      ‫وبطلــب البينــة مــن املدعــى عليــه التــي اســتعد بإحضارهــا يف هذه اجللســة‬\n      ‫قــال ليــس لــدي بينــة هكــذا قــال فأفهمتــه بــأن ليــس لــه إال ميــن املدعــي‬\n      ‫علــى نفــي دعــواه ففهــم ذلــك وقــال أطلــب ميينــه هكــذا قــال وبعــرض‬\n      ‫اليمــن علــى املدعــي بعــد تذكيــره بخطــر اليمــن الكاذبــة اســتعد‬\n      ‫باحللــف بعــد اإلذن لــه قائــا واهلل العظيــم أنــي لــم أقــم بضــرب املدعــى‬\n      ‫عليــه هــذا احلاضــر معــي ابتــداء كمــا لــم أقــم بإرســال رســائل تهديــد لــه‬\n      ‫قائــا (بتوطــاك) ابتــداء كمــا لــم أتلفــظ عليــه قائــا (يالنقــل ويــا قــواد‬\n      ‫ويــا حمــار) واهلل علــى مــا أقــول شــهيد هكــذا حلــف ‪ .‬فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه بدعــوى املدعــي‬\n\n\n‫‪263‬‬\n\f‫وحيــث دفــع املدعــى عليــه مبــا هــو مذكــور يف جوابــه وحيــث ال يوجــد‬\n‫لديــه بينــة علــى مــا دفــع بــه ولتوجــه اليمــن علــى املدعــي وأدائهــا كمــا‬\n‫طلبــت منــه لــذا فقــد قــررت مــا يلــي‪ :‬أوال‪ :‬ثبــت لــدي تهديــد املدعــى عليــه‬\n‫للمدعــي عــن طريــق إرســال رســالة باجلــوال بالصيــغ املذكــورة بالدعــوى‬\n‫وقيامــه بضــرب املدعــي ممــا نتــح عنــه إصابتــه بكدمــة يف الشــفة العليــا‬\n‫وســحجة بالركبــة اليســرى وقــررت تعزيــره لقــاء ذلــك بســجنه ملدة شــهر‬\n‫محســوبا منهــا مــدة توقيفــه وجلــده ســبعني جلــدة علــى دفعتــن مناصفــة‬\n‫بــن كل دفعــة وأخــرى عشــرة أيــام‪ .‬ثانيــا‪ :‬لــم يثبــت لــدي قيــام املدعــي‬\n‫بضــرب املدعــى عليــه ابتــداء وال تهديــده بالصيغــة املذكــورة ابتــداء وال‬\n‫التلفــظ عليــه بالصيــغ املذكــورة وصرفــت النظــر عــن ذلــك لعــدم ثبوتــه‬\n‫شــرعا ومبــا ســبق كلــه حكمــت وبعرضــه علــى الطرفــن قــرر املدعــي‬\n‫القناعــة بــه أمــا املدعــى عليــه فقــد قــرر املعارضــة عليــه وطلــب محكمــة‬\n‫االســتئناف فأفهمتــه بالتعليمــات ففهــم ذلــك وطلــب رفــع أوراق املعاملــة‬\n‫حملكمــة االســتئناف بــدون تقــدمي الئحــة اعتراضيــة فأجبتــه ملطلوبــة‬\n‫وعليــه فقــد قــررت رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف‬\n‫باملنطقــة الشــرقية لتدقيــق احلكــم حســب املتبــع واهلل املوفــق وصلــى‬\n                          ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم اخلميــس املوافــق ‪1434/09/10‬ه ـ‬\n‫افتتحــت اجللســة الثالثــة يف متــام الســاعة العاشــرة والنصــف صباح ـ ًا‬\n‫وفيهــا حضــر الســعودي بالســجل املدنــي رقــم (‪ ).....‬حــال كونــه وكيــا‬\n‫شــرعيا عــن املدعــي الســعودي بالســجل املدنــي رقــم (‪ ).....‬مبوجــب‬\n‫الوكالــة الصــادرة مــن كتابــة عــدل األحســاء الثانيــة برقــم (‪)13647‬‬\n‫يف ‪1430/4/11‬هـ ـ جلــد (‪ )2853‬والتــي تخولــه حــق املخاصمة واملطالبة‬\n\n\n                                                                                        ‫‪264‬‬\n\f      ‫واملرافعــة واملدافعــة وإقامــة الدعــوى وقبــول احلكــم أو االعتــراض‬\n      ‫عليــه والصلــح واإلقــرار واإلنــكار وطلــب اليمــن أو ردهــا واالســتالم‬\n      ‫والتســليم وحضــر حلضــوره املدعــى عليــه املذكــورة هويتــه ســابقا وبنــاء‬\n      ‫علــى رجــوع املعاملــة مــن محكمة االســتئناف باملنطقة الشــرقية مبوجب‬\n      ‫خطابهــم رقــم (‪ )34/1084364‬برفقــه القــرار الصــادرة مــن الدائــرة‬\n      ‫اجلزائيــة الثالثيــة األولــى‪ -‬ج‪ 1/‬رقــم (‪ )34232701‬يف ‪1434/6/6‬ه ـ‬\n      ‫ونــص احلاجــة منــه (وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫لوحــظ أوالً‪ :‬أن فضيلــة ناظــر القضيــة لــم يذكــر اســمه وصفتــه يف‬\n      ‫بدايــة القــرار وتكــرار ذلــك يف قــرارات عــدة فعلــى فضيلتــه مراعــاة‬\n      ‫ذلــك مســتقبال‪ .‬ثانيــا‪ :‬أن املدعــي واملدعــى عليــه بينهمــا صلــة رحــم أال‬\n      ‫يــرى فضيلتــه أن مثــل هــذه األحــكام قــد تزيــد اخلــاف بينهمــا ولعلــى‬\n      ‫فضيلتــه أن يبــذل مســاعي حملاولــة الصلــح بــن الطرفــن ملالحظــة مــا‬\n      ‫ذكــر وإكمــال الــازم ومــن ثــم إعــادة املعاملــة واهلل املوفق)أ‪.‬ه ـ عليــه‬\n      ‫توقيع وختم أصحاب الفضيلة كل من قاضي اســتئناف‪ ،‬د‪ .‬ف قاضي‬\n      ‫اســتئناف‪ ،‬رئيــس الدائــرة أفيــد أصحــاب الفضيلــة ‪ -‬وفقهــم اهلل ‪ -‬مبــا‬\n      ‫يلــي‪ :‬أوال‪ :‬بالنســبة للمالحظــة األولــى والثانيــة فتــم اســتدراك مــا ذكــره‬\n      ‫أصحــاب الفضيلــة ‪ -‬ســددهم اهلل ‪ -‬وإضافــة مــا طلبــوه‪ .‬ثانيــا‪ :‬بالنســبة‬\n      ‫للمالحظــة الثانيــة أفيــد أصحــاب الفضيلــة ‪ -‬أيدهــم اهلل بتوفيقــه ‪ -‬أنــه‬\n      ‫مت بــذل الوســع واجلهــد لإلصــاح بــن الطرفــن وإدخــال بعــض األخيــار‬\n      ‫لإلصــاح بينهمــا ومت تذكيرهمــا بقولــه تعالــى‪{ :‬فمــن عفــا وأصلــح‬\n      ‫فأجــره علــى اهلل} [الشــورى‪ ]40 :‬وقــول احلــق ســبحانه {والصلــح خيــر}‬\n      ‫[النســاء‪ .]128 :‬وقولــه ســبحانه‪{ :‬ادفــع بالتــي هــي أحســن فــإذا الــذي‬\n      ‫بينــك وبينــه عــداوة كأنــه ولــي حميــم ومــا يلقاهــا إال الذيــن صبــروا‬\n\n\n‫‪265‬‬\n\f‫ومــا يلقاهــا إال ذو حــظ عظيــم وإمــا ينزغنــك مــن الشــيطان نــزغ فاســتعذ‬\n‫بــاهلل إنــه هــو الســميع العليــم} [فصلــت‪ ]36-35-34:‬وقولــه تعالــى {خــذ‬\n‫العفــو وأمــر بالعــرف وأعــرض عــن اجلاهلــن وإمــا ينزغنــك مــن الشــيطان‬\n‫نــزغ فاســتعذ بــاهلل إنــه ســميع عليــم} [األعــراف‪ ]200-199:‬ونحــن‬\n‫اآلن يف شــهر رمضــان وهــو شــهر العفــو والتســامح وصفــاء القلــوب‬\n‫وتتضاعــف احلســنات للعافــن عــن النــاس واهلل يحــب احملســنني وذلــك‬\n‫لقولــه تعالى‪{:‬والكاظمــن الغيــظ والعافــن عــن النــاس واهلل يحــب‬\n‫احملســنني} [آل عمــران‪ .]134:‬رفــض وكيــل املدعــي الصلــح وقــال إن‬\n‫موكلــي ال يريــد الصلــح وال يســتطيع أحــد أن يجبــره عليــه هكــذا قــال‬\n‫وعليــه فقــد قــررت إعــادة كامــل أوراق املعاملــة حملكمــة االســتئناف‬\n‫لتقريــر مــا تــراه حيــال ذلــك واهلل ولــي التوفيــق واختتمــت اجللســة يف متــام‬\n‫احلاديــة عشــرة صباح ـ ًا وللبيــان حــرر يف ‪1434/09/10‬ه ـ وصلــى اهلل‬\n                                 ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n‫برقــم ‪ 34/1521668‬وتاريــخ ‪1434/10/7‬ه ـ املقيــدة لــدى احملكمــة‬\n‫برقــم ‪ 34/2309942‬وتاريــخ ‪1434/10/13‬هـ املرفق بهاالقرار الصادر‬\n‫مــن فضيلــة املــازم القضائــي باحملكمــة الشــيخ (‪ ).....‬املســجل برقــم‬\n‫‪ 34186344‬وتاريــخ ‪1434/4/13‬ه ـ اخلــاص بدعــوى‪ ).....(/‬ضــد‪).....(/‬‬\n‫يف قضيــة مضاربــة وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه ‪ .‬حيــث ســبق دراســة القــرار وصــورة ضبطــه وباإلطــاع‬\n‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء‬\n\n\n                                                                                         ‫‪266‬‬\n\f      ‫علــى قرارنــا رقــم‪ 34232701‬يف ‪1434/6/6‬ه ـ قررنــا املصادقــه علــى‬\n      ‫احلكــم بعــد االجــراء االخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                 ‫وآلــه وصحبــه وســلم حــرر يف ‪1434/11/10‬ه ـ‬\n\n\n\n\n‫‪267‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":261,"source_page_end":267,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"03ff0fd23e0459331e66565f3459b6d2ce404d0a7d6f958cf9ea2391708cec68","normalized_text_hash":"0f2c545c19a2918b07a8c69cf047ffbe8836f7c8565f0a9a92eb3f53ea938cab","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p261-34186344"},{"id":"701204a7-5b0a-5c3c-98a9-3ea1decd9880","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء الغير (حق خاص) -باغ كيدي -مطالبة املدعي بالتعزير- إنكار املدعى عليه الدعوى -النظر يف كيدية الباغ الحق للفصل يف موضوعه -مين املدعى عليه على نفي الدعوى -عدم ثبوت كيدية الباغ -رد الدعوى .","document_number":"33480435","case_number":"33631269","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املوافقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/27","year":"1434","subject":"إيذاء الغير (حق خاص) -باغ كيدي -مطالبة املدعي بالتعزير- إنكار املدعى عليه الدعوى -النظر يف كيدية الباغ الحق للفصل يف موضوعه -مين املدعى عليه على نفي الدعوى -عدم ثبوت كيدية الباغ -رد الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/12/27 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33480435 :‬‬\n                    ‫َر ْق ُم الدعوى‪33631269 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3444427‬تاريخه‪1434/02/23 :‬هـ‬\n\n\n ‫إيــذاء الغيــر (حــق خــاص)‪ -‬بــاغ كيــدي‪ -‬مطالبــة املدعــي بالتعزيــر‪-‬‬\n ‫إنــكار املدعــى عليــه الدعــوى‪ -‬النظــر يف كيديــة البــاغ الحــق للفصــل‬\n ‫يف موضوعــه ‪ -‬ميــن املدعــى عليــه علــى نفــي الدعــوى‪ -‬عــدم ثبــوت‬\n                                          ‫كيديــة البــاغ‪ -‬رد الدعــوى ‪.‬‬\n\n\n\n\n ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة‬\n                                                           ‫يف تســبيب حكمــه ‪.‬‬\n\n\n\n\n ‫ادعــى املدعــي بــأن املدعــى عليــه قام بطــرده من العمل لديــه إثر خالفات‬\n ‫بينهمــا‪ ،‬فتقــدم ضــده بشــكوى لــدى مكتــب العمــل‪ ،‬وعلــى إثــر ذلــك‬\n ‫قــدم املدعــى عليــه ضــده بالغــا كيديــا إلدارة الوافديــن يتضمــن هروبــه‬\n ‫مــن العمــل مــع كونــه هــو مــن منعــه مــن مزاولــة عملــه كمــا أنــه تلفــظ‬\n ‫عليــه مبــا جــاء يف دعــواه‪ ،‬ولــذا فقــد طلــب احلكــم عليــه بعقوبــة تعزيريــة‬\n ‫لقــاء ذلــك‪ -‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى مــن تقدميــه لبــاغ‬\n ‫ضــد املدعــي إلدارة الوافديــن يتضمــن هروبــه مــن العمــل ودفــع بــأن‬\n ‫هــذا البــاغ ليــس كيديــا لكــون املدعــي تغيــب عــن العمــل دون عــذر‪،‬‬\n ‫وأنكــر مــا جــاء يف الدعــوى مــن تلفظــه علــى املدعــي‪ -‬املدعــي ليــس‬\n\n                                                                                       ‫‪268‬‬\n\f      ‫لديــه بينــة علــى مــا نســبه إلــى املدعــى عليــه مــن التلفــظ وطلــب ميينــه علــى‬\n      ‫نفــي ذلــك فأداهــا طبــق مــا طلــب منــه‪ -‬البــاغ الــذي يدعــي املدعــي بأنــه‬\n      ‫كيــدي لــم يتــم الفصــل فيــه مــن اجلهــة املختصــة والنظــر يف كيديتــه‬\n      ‫مــن عدمهــا فــرع عــن الفصــل يف موضوعــه‪ -‬قضــت احملكمــة بــرد‬\n      ‫دعــوى املدعــي ضــد املدعــى عليــه لعــدم ثبــوت موجبهــا‪ -‬قنــع املدعــى‬\n      ‫عليــه باحلكــم وعــارض عليــه املدعــي‪ -‬قــررت محكمــة االســتئناف‬\n                                                                ‫املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بنجــران برقــم ‪ 33631269‬وتاريــخ ‪1433/10/29‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 331921937‬وتاريــخ ‪1433/10/29‬ه ـ ففــي يــوم‬\n      ‫االثنني املوافق‪1433/12/27‬هـ افتتحت اجللســة الســاعة ‪ 10 : 30‬وفيها‬\n      ‫‪ .....‬حضــر ســوداني اجلنســية مبوجــب رخصــة اإلقامــة رقــم ‪ .....‬وادعــى‬\n      ‫علــى احلاضــر معــه يف مجلــس احلكــم ‪ ...‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم ‪ .....‬قائــا يف دعــواه عليــه إن املدعــى عليــه هــذا‬\n      ‫احلاضــر ابــن كفيلــي وقــد حصلــت بينــي وبينــه خالفــات متعلقــة بالعمــل‬\n      ‫قــام علــى إثرهــا بطــردي وملــا تقدمــت بشــكوى لــدى مكتــب العمــل‬\n      ‫قــام فــور ًا بالتقــدم ضــدي ببــاغ كيــدي إلــى إدارة الوافديــن يدعــي‬\n      ‫فيــه أننــي هربــت مــن العمــل وعلــى إثــر ذلــك حضــر إلــى مقــر ســكني‬\n      ‫هــو وأحــد أفــراد األمــن باجلــوازات وتهجــم علــي وطلــب مــن رجــل األمــن‬\n      ‫اصطحابــي إلــى إدارة الوافديــن وأثنــاء ذلــك قــال لــي املدعــى عليــه‬\n\n‫‪269‬‬\n\f‫(بتتــأدب) أطلــب تعزيــره لقــاء بالغــه الكيــدي ضــدي وتلفظــه علــي‬\n‫مبــا ذكــر هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليــه وســؤاله‬\n‫اجلــواب أجــاب بقولــه مــا ذكــره املدعــي يف دعــواه مــن أننــي تقدمــت‬\n‫ضــده ببــاغ هــروب إلــى إدارة الوافديــن فهــذا صحيــح إال أن هــذا البــاغ‬\n‫ليــس كيديــا فقــد تغيــب املدعــي عــن مقــر العمــل ملــدة أكثــر مــن ثالثــة‬\n‫أيــام ولــم يســتأذن منــي فيحــق لــي مبوجــب نظــام العمــل أن أتقــدم ضــده‬\n‫ببــاغ هــروب وبعــد أن تقدمــت بالبــاغ املذكــور طلبــت مــن رجــل األمــن‬\n‫باجلــوازات أن يرافقنــي لداللتهــم علــى ســكنه ليقومــوا باصطحابــه وأما‬\n‫مــا ذكــره املدعــي مــن أننــي تلفظــت عليــه بقولــي لــه (بتتــأدب) فهــذا‬\n‫غيــر صحيــح فلــم أتلفــظ عليــه بذلــك وال غيــره وقــد أقــام علــي هــذه‬\n‫الدعــوى لغــرض كيــدي هــذه إجابتــي وبعــرض ذلــك علــى املدعــي قــال‬\n‫إننــي غــادرت محــل العمــل يــوم األربعــاء وعــدت يــوم األحــد وســبب ذلــك‬\n‫أننــي ذهبــت ألداء العمــرة وقــد جــرى العــرف يف محــل عملنــا أن الكفيــل‬\n‫يتســامح يف ذلــك ال ســيما وأننــي قــد أبلغــت زميلــي يف العمــل بذلــك‬\n‫وبطلــب البينــة مــن املدعــي علــى مــا ذكــر يف دعــواه مــن أن بــاغ الهــروب‬\n‫املقــدم ضــده كان كيديـ ًا قــال إن املدعــى عليــه لــم يتقــدم بهــذا البــاغ‬\n‫إال بعــد أن علــم بأننــي تقدمــت بشــكوى ضــده ملكتــب العمــل وأنــا لــم‬\n‫أهــرب بــل هــو الــذي منعنــي مــن العمل‪.‬أ‪.‬ه ـ وبســؤاله هــل لديــه زيــادة‬\n‫بينــة بشــأن ذلــك قــال ال ‪.‬أ‪.‬ه ـ وبطلــب البينــة مــن املدعــي علــى مــا ذكــر‬\n‫يف دعــواه مــن تلفــظ املدعــى عليــه مبــا ذكــر قــال إن املدعــى عليــه قــد‬\n‫تلفــظ بذلــك أمــام بعــض أفــراد اجلــوازات إال أننــي عاجــز عــن إحضارهــم‬\n‫للشــهادة بذلــك فأفهمتــه أن لــه ميــن املدعــى عليــه علــى نفــي مــا جــاء‬\n‫يف دعــواه مــن التلفــظ عليــه فقــال أطلــب ميينــه علــى نفــي ذلــك وبعــرض‬\n\n\n                                                                                      ‫‪270‬‬\n\f      ‫ذلــك علــى املدعــى عليــه اســتعد ببــذل اليمــن فأذنــت لــه فحلــف قائــا‬\n      ‫واهلل الــذي ال إلــه إال هــو عالــم الغيــب والشــهادة إننــي لــم أتلفــظ علــى‬\n      ‫املدعــي بقولــي لــه بتتــأدب واهلل واهلل واهلل‪.‬أ‪.‬ه ـ ثــم جــرى منــي ســؤال‬\n      ‫الطرفــن هــل الزالــت الشــكوى املقدمــة ملكتــب العمــل مســتمرة وهــل‬\n      ‫ال زال بــاغ الهــروب املذكــور قائمـ ًا فقــاال نعــم ‪.‬أ‪.‬ه ـ فبنــاء علــى مــا تقدم‬\n      ‫مــن الدعــوى واإلجابــة وبعــد دراســة القضيــة وتأملهــا ومبــا أن املدعــى‬\n      ‫عليــه أنكــر مــا جــاء يف دعــوى املدعــي مــن تلفظــه عليــه مبــا ذكــر وألن‬\n      ‫املدعــي لــم يقــم بينــة تثبــت دعــواه بذلــك وألنــه طلــب ميــن خصمــه علــى‬\n      ‫نفــي دعــواه بالتلفــظ وألن املدعــى عليــه حلــف اليمــن الشــرعية طبــق مــا‬\n      ‫طلــب منــه‪ ،‬وألن مــا ادعــى بــه املدعــي مــن كيديــة البــاغ املقــدم مــن‬\n      ‫املدعــى عليــه ضــده بهروبــه ينبنــي ثبوتــه علــى مــا ســيصدر مــن مكتــب‬\n      ‫العمــل بشــأن الشــكوى التــي قدمهــا لديــه املدعــي ضــد املدعــى عليــه‪،‬‬\n      ‫كمــا أن بــاغ الهــروب الزال قائمـ ًا ولــم يتــم إلغائــه مــن اجلهــة املختصــة‬\n      ‫بــإدارة الوافديــن‪ ،‬لــكل ذلــك فقــد حكمــت بــرد دعــوى املدعــي ضــد‬\n      ‫املدعــى عليــه لعــدم ثبــوت موجبهــا وبعــرض ذلــك علــى املدعــي قــرر‬\n      ‫اعتراضــه علــى احلكــم بالئحــة اعتراضيــة فجــرى تســليمه صــورة مــن‬\n      ‫قــرار احلكــم وأفهمتــه أن مــدة االعتــراض ثالثــون يوم ـ ًا تبــدأ مــن يــوم‬\n      ‫غــد فــإذا لــم يقــدم الئحتــه االعتراضيــة خاللهــا فــإن حقــه يف طلــب‬\n      ‫االســتئناف يســقط كمــا قــرر املدعــى عليــه قناعتــه باحلكــم وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                             ‫حــرر يف ‪1433/12 / 27‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n\n\n‫‪271‬‬\n\f‫الــواردة مــن فضيلــة القائــم بعمــل رئيــس احملكمــة اجلزائيــة بنجــران‬\n‫برقــم ‪ 331921937‬وتاريــخ ‪1434/2/2‬ه املرفــق بهــا القــرار الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ................ /‬برقــم ‪33480435‬‬\n‫وتاريــخ ‪1433/12/27‬ه اخلــاص بدعــوى ‪ - ...............‬ســوداني‬\n‫اجلنســية‪،‬ضد‪ ................. /‬يف قضيــة (بــاغ كيــدي وتلفــظ) علــى‬\n‫الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت‬\n‫املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                           ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                  ‫‪272‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"2173441a-2c37-5232-887f-9ccbd335e740","source_page_start":268,"source_page_end":272,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"43224c6afb7cf74343eed5c0638695ffe87e19e2b48037583eb909275d2ce615","normalized_text_hash":"08864d41ec583b5c41e7010b506cb3f887f5dd7dd498026d705dd6de2b27f99b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v15-p268-33480435"}]$archive_payload$::jsonb AS data)
